request_examples.content:
POST / HTTP/1.1
Host: live.tencentcloudapi.com
Content-Type: application/json
X-TC-Action: ModifyAuditTemplate
<公共请求参数>

{
    "AuditTemplate": {
        "TemplateId": 55514,
        "TemplateName": "直播审核_test",
        "Description": "直播审核_test",
        "AuditImage": true,
        "AuditAudio": true,
        "AuditText": 1,
        "SnapshotInterval": 50,
        "AudioInterval": 30,
        "CosBucket": "live-test",
        "CosRegion": "ap-shanghai",
        "CosFilePath": "/Audit/{Year}-{Month}-{Day}/{StreamID}-Audit-{Hour}-{Minute}-{Second}{Ext}",
        "EnableFailoverCos": false,
        "SceneInfos": [
            {
                "BizInfos": [
                    {
                        "BizType": "1_1_7_55514",
                        "Status": true,
                        "StrategyType": "ShortAudio",
                        "StrategyConfig": "{\"ability\":{\"asr_text\":true,\"audio\":true},\"asr_text_labels\":{\"ad\":[\"AdvertisingDiversion\",\"FinancialAdvertising\"]},\"audio_labels\":{},\"user_text_libs\":[\"0fd0600e-0603-41e8-a985-ae49a73fbe9f\"]}"
                    },
                    {
                        "BizType": "1_1_2_55514",
                        "Status": true,
                        "StrategyType": "Image",
                        "StrategyConfig": "{\"ability\":{\"image\":true,\"ocr_text\":true},\"ocr_text_labels\":{\"ad\":[\"AdvertisingDiversion\",\"FinancialAdvertising\"]},\"image_labels\":{\"illegal\":[\"Delinquenent\",\"NonMainstream\",\"Illegal\",\"Contraband\",\"PersonalPrivacy\",\"Nausea\"],\"ad\":[\"QRCode\",\"LOGO\"]},\"user_text_libs\":[\"0fd0600e-0603-41e8-a985-ae49a73fbe9f\"]}"
                    },
                    {
                        "BizType": "1_1_1_55514",
                        "Status": true,
                        "StrategyType": "Text",
                        "StrategyConfig": "{\"ability\":{\"text\":true},\"ignore_word_conf\":{\"keyword_disable\":false,\"model_disable\":false,\"rule_disable\":false},\"text_labels\":{\"ad\":[\"AdvertisingDiversion\",\"FinancialAdvertising\"]},\"user_text_libs\":[\"0fd0600e-0603-41e8-a985-ae49a73fbe9f\"]}"
                    }
                ]
            }
        ]
    }
}

